// stats' stl and supsmu, forecast's mstl (one seasonal period), seasadj, nsdiffs and ocsb.test. Written for rStats.js
// from the behaviour specification oracle/tsmeta-behaviour.md with the details found in experiments/tsmeta120-log.md
// (stl: items 19-27, from Cleveland, Cleveland, McRae and Terpenning 1990; supsmu: items 48-49, from Friedman 1984;
// mstl, nsdiffs, ocsb: items 39-42, 47). No R or package source was read.

import { lm, type LmResult } from "../models/lm.js";
import { OCSB_CRITICAL, OCSB_M } from "./ocsbCritical.js";
import { standardise } from "./scale.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const STL_KEYS = /* @__PURE__ */ new Set([
  "frequency", "sWindow", "sDegree", "tWindow", "tDegree", "lWindow", "lDegree", "sJump", "tJump", "lJump", "robust",
  "inner", "outer",
]);
const SUPSMU_KEYS = ["span", "bass"] as const;
const MSTL_KEYS = ["frequency", "sWindow", "robust"] as const;
const NSDIFFS_KEYS = ["frequency", "test", "maxD"] as const;
const OCSB_TEST_KEYS = ["frequency", "maxlag", "lagMethod"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

// ---------------------------------------------------------------------------------------------------------------
// stl

const nextOdd = (x: number): number => { const r = Math.round(x); return r % 2 === 0 ? r + 1 : r; };

/** loess on positions 1..n (the q nearest consecutive points) evaluated at the positions `at`. */
function loessAt(y: readonly number[], rw: readonly number[], at: readonly number[], q: number, degree: number): number[] {
  const n = y.length; const qq = Math.min(q, n);
  return at.map((x) => {
    let left: number, right: number;
    if (x < 1) { left = 1; right = qq; } else if (x > n) { left = n - qq + 1; right = n; }
    else { left = Math.max(1, Math.min(Math.round(x) - Math.floor((qq - 1) / 2), n - qq + 1)); right = left + qq - 1; }
    let h = Math.max(x - left, right - x);
    if (q > n) h += Math.floor((q - n) / 2); // the window widened by (q - n) %/% 2 when q > n (log 19)
    const w: number[] = []; let sw = 0;
    for (let j = left; j <= right; j++) {
      const r = Math.abs(j - x);
      // tricube weights with lowess's thresholds (1 at r <= 0.001 h, 0 beyond 0.999 h)
      let v = r <= 0.001 * h ? 1 : r > 0.999 * h ? 0 : (1 - (r / h) ** 3) ** 3;
      v *= rw[j - 1]!; w.push(v); sw += v;
    }
    if (!(sw > 0)) return NaN;
    for (let k = 0; k < w.length; k++) w[k]! /= sw;
    if (degree === 1) {
      let a = 0; for (let k = 0; k < w.length; k++) a += w[k]! * (left + k);
      let c = 0; for (let k = 0; k < w.length; k++) c += w[k]! * (left + k - a) ** 2;
      if (Math.sqrt(c) > 0.001 * (n - 1)) for (let k = 0; k < w.length; k++) w[k]! *= 1 + ((x - a) * (left + k - a)) / c;
    }
    let s = 0; for (let k = 0; k < w.length; k++) s += w[k]! * y[left + k - 1]!;
    return s;
  });
}

/** loess at 1, 1 + jump, ..., n, linearly interpolated in between. */
function smoothJump(y: readonly number[], rw: readonly number[], q: number, degree: number, jump: number): number[] {
  const n = y.length;
  if (n <= 2) return y.slice();
  const at: number[] = []; for (let t = 1; t <= n; t += jump) at.push(t);
  if (at[at.length - 1] !== n) at.push(n);
  const v = loessAt(y, rw, at, q, degree);
  if (jump === 1) return v;
  return interpolate(at, v, n);
}

function interpolate(at: readonly number[], v: readonly number[], n: number): number[] {
  const out = new Array<number>(n); let k = 0;
  for (let t = 1; t <= n; t++) {
    while (k < at.length - 2 && at[k + 1]! < t) k++;
    const x0 = at[k]!, x1 = at[k + 1] ?? x0;
    out[t - 1] = x1 === x0 ? v[k]! : v[k]! + ((v[k + 1]! - v[k]!) * (t - x0)) / (x1 - x0);
  }
  return out;
}

/** A trailing moving average of length len (the first len - 1 positions dropped). */
function movAvg(x: readonly number[], len: number): number[] {
  const out: number[] = []; let s = 0;
  for (let i = 0; i < x.length; i++) { s += x[i]!; if (i >= len) s -= x[i - len]!; if (i >= len - 1) out.push(s / len); }
  return out;
}

const median = (v: readonly number[]): number => {
  const s = v.slice().sort((a, b) => a - b); const m = s.length >> 1;
  return s.length % 2 ? s[m]! : (s[m - 1]! + s[m]!) / 2;
};

/**
 * Options of {@link stl}.
 *
 * @category Time series
 */
export interface StlOptions {
  /** The seasonal period (R's frequency). */
  frequency: number;
  /** The seasonal loess span (odd, >= 7 recommended) or "periodic". */
  sWindow: number | "periodic";
  sDegree?: 0 | 1;
  tWindow?: number;
  tDegree?: 0 | 1;
  lWindow?: number;
  lDegree?: 0 | 1;
  sJump?: number;
  tJump?: number;
  lJump?: number;
  robust?: boolean;
  inner?: number;
  outer?: number;
}

/**
 * Result of {@link stl}.
 *
 * @category Time series
 */
export interface StlResult {
  seasonal: number[];
  trend: number[];
  remainder: number[];
  /** The robustness weights of the last pass (all 1 without robustness iterations). */
  weights: number[];
  /** The windows (s, t, l), degrees, jumps and iteration counts used. */
  win: [number, number, number];
  deg: [number, number, number];
  jump: [number, number, number];
  inner: number;
  outer: number;
}

/**
 * Seasonal-trend decomposition by loess (Cleveland et al. 1990). Equivalent to R's `stl()`. It differs in that the
 * robustness weights use the true median of |remainder| (R takes a wrong order statistic for some even-length series:
 * R bug 19370, see the documentation's departures from R).
 *
 * @category Time series
 */
export function stl(x: readonly number[], options: StlOptions): StlResult {
  checkOptions(options, STL_KEYS, "stl"); // generated: option-keys.mjs
  const y = x.map(Number); const n = y.length; const np = options.frequency;
  if (y.some((v) => !Number.isFinite(v))) throw new RangeError("stl: series contains missing or infinite values");
  if (!(np >= 2) || n <= 2 * np) throw new RangeError("stl: series is not periodic or has less than two periods");
  const periodic = options.sWindow === "periodic";
  const sWindow = periodic ? 10 * n + 1 : nextOdd(options.sWindow as number);
  const sDegree = periodic ? 0 : options.sDegree ?? 0;
  const tDegree = options.tDegree ?? 1;
  const lDegree = options.lDegree ?? tDegree;
  const lWindow = nextOdd(options.lWindow ?? np);
  const tWindow = nextOdd(options.tWindow ?? Math.ceil((1.5 * np) / (1 - 1.5 / sWindow)));
  const sJump = options.sJump ?? Math.ceil(sWindow / 10); const tJump = options.tJump ?? Math.ceil(tWindow / 10);
  const lJump = options.lJump ?? Math.ceil(lWindow / 10);
  const robust = options.robust ?? false;
  const inner = options.inner ?? (robust ? 1 : 2); const outer = options.outer ?? (robust ? 15 : 0);
  let trend = new Array<number>(n).fill(0); let rw = new Array<number>(n).fill(1); let season = new Array<number>(n).fill(0);
  const ones = new Array<number>(n).fill(1);
  for (let o = 0; o <= outer; o++) {
    for (let it = 0; it < inner; it++) {
      const d = y.map((v, i) => v - trend[i]!);
      const C = new Array<number>(n + 2 * np).fill(0);
      for (let p = 0; p < np; p++) {
        const idx: number[] = []; for (let t = p; t < n; t += np) idx.push(t);
        const k = idx.length; const dk = idx.map((t) => d[t]!); const wk = idx.map((t) => rw[t]!);
        let sm: number[];
        if (sJump > 1) {
          const at: number[] = []; for (let t = 1; t <= k; t += sJump) at.push(t);
          if (at[at.length - 1] !== k) at.push(k);
          const v = loessAt(dk, wk, at, sWindow, sDegree);
          sm = [loessAt(dk, wk, [0], sWindow, sDegree)[0]!, ...interpolate(at, v, k), loessAt(dk, wk, [k + 1], sWindow, sDegree)[0]!];
        } else sm = loessAt(dk, wk, Array.from({ length: k + 2 }, (_, i) => i), sWindow, sDegree);
        for (let j = 0; j < k + 2; j++) C[p + np * j] = sm[j]!;
      }
      const L = smoothJump(movAvg(movAvg(movAvg(C, np), np), 3), ones, lWindow, lDegree, lJump);
      season = y.map((_, i) => C[np + i]! - L[i]!);
      trend = smoothJump(y.map((v, i) => v - season[i]!), rw, tWindow, tDegree, tJump);
    }
    if (o < outer) {
      const R = y.map((v, i) => Math.abs(v - season[i]! - trend[i]!));
      // the true median (R bug 19370 takes a wrong order statistic for some even n, log 26-27)
      const h = 6 * median(R);
      rw = R.map((r) => { const u = r / h; return u <= 0.001 ? 1 : u > 0.999 ? 0 : (1 - u * u) ** 2; });
    }
  }
  if (periodic) {
    // the seasonal replaced by its mean at each cycle position
    const sums = new Array<number>(np).fill(0), cnt = new Array<number>(np).fill(0);
    season.forEach((v, i) => { sums[i % np]! += v; cnt[i % np]!++; });
    season = season.map((_, i) => sums[i % np]! / cnt[i % np]!);
  }
  return {
    seasonal: season, trend, remainder: y.map((v, i) => v - season[i]! - trend[i]!), weights: rw,
    win: [sWindow, tWindow, lWindow], deg: [sDegree, tDegree, lDegree], jump: [sJump, tJump, lJump], inner, outer,
  };
}

// ---------------------------------------------------------------------------------------------------------------
// supsmu

function runLine(x: readonly number[], y: readonly number[], span: number, cv: boolean): { fit: number[]; res: number[] } {
  const n = x.length;
  let k = Math.max(2, Math.floor((span * n) / 2 + 0.5)); // rounded half up (log 49)
  k = Math.min(k, Math.floor((n - 1) / 2));
  const fit = new Array<number>(n), res = new Array<number>(n);
  const tiny = (1e-3 * (x[n - 1]! - x[0]!)) ** 2;
  for (let i = 0; i < n; i++) {
    // the window of 2k + 1 consecutive points kept at that size at the ends (log 48)
    const lo = Math.max(0, Math.min(i - k, n - 1 - 2 * k)); const hi = lo + 2 * k; const m = hi - lo + 1;
    let xm = 0, ym = 0; for (let j = lo; j <= hi; j++) { xm += x[j]!; ym += y[j]!; } xm /= m; ym /= m;
    let sxx = 0, sxy = 0; for (let j = lo; j <= hi; j++) { sxx += (x[j]! - xm) ** 2; sxy += (x[j]! - xm) * (y[j]! - ym); }
    const slope = sxx > tiny; const b = slope ? sxy / sxx : 0;
    fit[i] = ym + b * (x[i]! - xm);
    if (cv) { const hh = 1 / m + (slope ? (x[i]! - xm) ** 2 / sxx : 0); res[i] = Math.abs(y[i]! - fit[i]!) / (1 - hh); }
  }
  return { fit, res };
}

/**
 * Friedman's super smoother (running lines with a cross-validated variable span). Equivalent to R's `supsmu()`.
 * Tied x are not handled as R does.
 *
 * @category Time series
 */
export function supsmu(x: readonly number[], y: readonly number[], options: { span?: number | "cv"; bass?: number } = {}): { x: number[]; y: number[] } {
  checkOptions(options, SUPSMU_KEYS, "supsmu"); // generated: option-keys.mjs
  const ord = x.map((_, i) => i).filter((i) => Number.isFinite(x[i]!) && Number.isFinite(y[i]!)).sort((a, b) => x[a]! - x[b]!);
  const xs = ord.map((i) => x[i]!), ys = ord.map((i) => y[i]!);
  const span = options.span ?? "cv"; const bass = options.bass ?? 0;
  if (typeof span === "number") return { x: xs, y: runLine(xs, ys, span, false).fit };
  const sp = [0.05, 0.2, 0.5];
  const fits = sp.map((s) => runLine(xs, ys, s, true));
  const rs = fits.map((f) => runLine(xs, f.res, 0.2, false).fit);
  const n = xs.length;
  const best = new Array<number>(n);
  for (let i = 0; i < n; i++) {
    let b = 0; for (let k = 1; k < 3; k++) if (rs[k]![i]! < rs[b]![i]!) b = k;
    best[i] = sp[b]!;
    if (bass > 0) {
      const rmin = rs[b]![i]!, w = rs[2]![i]!;
      if (rmin < w && rmin > 0) best[i] = best[i]! + (0.5 - best[i]!) * Math.max(1e-7, rmin / w) ** (10 - bass);
    }
  }
  const bs = runLine(xs, best, 0.2, false).fit.map((v) => Math.min(0.5, Math.max(0.05, v)));
  const mix = bs.map((s, i) => {
    if (s >= 0.2) { const f = (s - 0.2) / 0.3; return (1 - f) * fits[1]!.fit[i]! + f * fits[2]!.fit[i]!; }
    const f = (0.2 - s) / 0.15; return (1 - f) * fits[1]!.fit[i]! + f * fits[0]!.fit[i]!;
  });
  return { x: xs, y: runLine(xs, mix, 0.05, false).fit };
}

// ---------------------------------------------------------------------------------------------------------------
// mstl, seasadj, nsdiffs, ocsb.test

/**
 * Result of {@link mstl}.
 *
 * @category Time series
 */
export interface MstlResult {
  data: number[];
  trend: number[];
  /** The seasonal component (absent for a non-seasonal series). */
  seasonal?: number[];
  remainder: number[];
  frequency: number;
}

/**
 * forecast's `mstl()` for one seasonal period: stl(x, s.window = 11); for a non-seasonal series (or fewer than two
 * periods) the trend is supsmu(1:n, x).
 * Equivalent to `forecast::mstl()` in R.
 *
 * @category Time series
 */
export function mstl(x: readonly number[], options: { frequency?: number; sWindow?: number | "periodic"; robust?: boolean } = {}): MstlResult {
  checkOptions(options, MSTL_KEYS, "mstl"); // generated: option-keys.mjs
  const m = options.frequency ?? 1; const n = x.length; const data = x.map(Number);
  if (m > 1 && n > 2 * m) {
    const r = stl(data, { frequency: m, sWindow: options.sWindow ?? 11, robust: options.robust ?? false });
    return { data, trend: r.trend, seasonal: r.seasonal, remainder: r.remainder, frequency: m };
  }
  const t = supsmu(data.map((_, i) => i + 1), data).y;
  return { data, trend: t, remainder: data.map((v, i) => v - t[i]!), frequency: m };
}

/**
 * The seasonally adjusted series of an mstl / stl decomposition (data - seasonal). Equivalent to `forecast::seasadj()` in R.
 *
 * @category Time series
 */
export function seasadj(dec: MstlResult): number[] {
  return dec.seasonal ? dec.data.map((v, i) => v - dec.seasonal![i]!) : dec.data.slice();
}

const variance = (v: readonly number[]): number => {
  const m = v.reduce((a, b) => a + b, 0) / v.length; return v.reduce((a, b) => a + (b - m) ** 2, 0) / (v.length - 1);
};

/**
 * The number of seasonal differences: 1 when the seasonal strength of mstl, max(0, 1 - var(remainder) /
 * var(seasonal + remainder)), exceeds 0.64 (test "seas"), or by the OCSB test. Equivalent to `forecast::nsdiffs()` in R.
 *
 * @category Time series
 */
export function nsdiffs(x: readonly number[], options: { frequency: number; test?: "seas" | "ocsb"; maxD?: number }): number {
  checkOptions(options, NSDIFFS_KEYS, "nsdiffs"); // generated: option-keys.mjs
  const m = options.frequency; const maxD = options.maxD ?? 1; const test = options.test ?? "seas";
  // the tests do not depend on the scale: the series divided by a power of two (exact), so that 1e+-300 works
  let y = standardise(x.filter(Number.isFinite));
  if (m <= 1 || y.every((v) => v === y[0])) return 0;
  let D = 0;
  const dodiff = (v: readonly number[]): boolean => {
    if (v.length < 2 * m + 1) return false;
    if (test === "seas") {
      const dec = mstl(v, { frequency: m });
      if (!dec.seasonal) return false;
      const sr = dec.seasonal.map((s, i) => s + dec.remainder[i]!);
      return Math.max(0, 1 - variance(dec.remainder) / variance(sr)) > 0.64;
    }
    // R's nsdiffs calls ocsb.test with lag.method "AIC" and maxlag 3, which fails (and nsdiffs returns 0) when the
    // series has at most m + 5 values. The lag is chosen correctly here, unlike R's off-by-one (ocsbTest, log 89-90)
    if (v.length <= m + 5) return false;
    const r = ocsbTest(v, { frequency: m, lagMethod: "AIC", maxlag: 3 });
    return r.statistic > r.critical;
  };
  while (D < maxD && dodiff(y)) { D++; y = y.slice(m).map((v, i) => v - y[i]!); if (y.every((v) => v === y[0])) break; }
  return D;
}

/**
 * The 5% critical value of the OCSB test for period m (the table read off R; log m interpolation beyond 400). Not an R function.
 *
 * @category Time series
 */
export function ocsbCritical(m: number): number {
  const i = OCSB_M.indexOf(m);
  if (i >= 0) return OCSB_CRITICAL[i]!;
  const last = OCSB_M.length - 1;
  if (m > OCSB_M[last]!) return OCSB_CRITICAL[last]!;
  let k = 0; while (OCSB_M[k + 1]! < m) k++;
  const a = Math.log(OCSB_M[k]!), b = Math.log(OCSB_M[k + 1]!);
  return OCSB_CRITICAL[k]! + ((OCSB_CRITICAL[k + 1]! - OCSB_CRITICAL[k]!) * (Math.log(m) - a)) / (b - a);
}

// The OCSB regression with L lags on the rows t >= t0 of y; the AR(L) prefilter of w = Delta_m Delta_1 y is fitted on
// w's rows from arFrom (L for the test itself, the largest candidate's lag when lags are compared on a common sample).
function ocsbRegression(y: readonly number[], m: number, L: number, t0: number, arFrom: number): LmResult {
  const n = y.length;
  const dd = (t: number): number => y[t]! - y[t - 1]! - y[t - m]! + y[t - m - 1]!;
  const dm = (t: number): number => y[t]! - y[t - m]!;
  const d1 = (t: number): number => y[t]! - y[t - 1]!;
  let a: number[] = [];
  if (L > 0) {
    const w: number[] = []; for (let t = m + 1; t < n; t++) w.push(dd(t));
    const X: number[][] = [], Y: number[] = [];
    for (let t = arFrom; t < w.length; t++) { X.push(Array.from({ length: L }, (_, i) => w[t - 1 - i]!)); Y.push(w[t]!); }
    a = lm(X, Y, { intercept: false }).coefficients;
  }
  const rows: number[][] = [], resp: number[] = [];
  for (let t = t0; t < n; t++) {
    let z4 = dm(t - 1), z5 = d1(t - m);
    for (let i = 1; i <= L; i++) { z4 -= a[i - 1]! * dm(t - 1 - i); z5 -= a[i - 1]! * d1(t - m - i); }
    rows.push([...Array.from({ length: L }, (_, i) => dd(t - 1 - i)), z4, z5]); resp.push(dd(t));
  }
  return lm(rows, resp, { intercept: false });
}

/**
 * The Osborn-Chui-Smith-Birchenhall test for a seasonal unit root: with w = Delta_m Delta_1 y and L lags, the AR(L)
 * coefficients a of w by least squares (no mean), then the regression of w_t on w_{t-1..L} and the two auxiliary
 * series filtered by a, (1 - a(B)) Delta_m y_{t-1} and (1 - a(B)) Delta_1 y_{t-m}, without a constant; the statistic
 * is the t value of the second (log 41, 80). Equivalent to `forecast::ocsb.test()` in R. With `lagMethod` "fixed" (the
 * default) L = `maxlag` (R's default 0). With "AIC", "BIC" or "AICc" the lags 0..maxlag are compared on a common
 * sample (the rows of maxlag lags, the prefilter too) by the lm criterion with k = coefficients + 1 (AICc = AIC +
 * 2k(k + 1) / (n - k - 1), forecast's help), and the chosen L is used. **This departs from R:** forecast 9.0.2 compares
 * L = 1..maxlag that way but reports and uses one lag fewer than the chosen L (log 89-90, an off-by-one; the user's
 * decision 2026-11-27 is not to imitate it). Candidates with a perfect fit (and for AICc, n <= k + 1) are skipped.
 *
 * @category Time series
 */
export function ocsbTest(
  x: readonly number[],
  options: { frequency: number; maxlag?: number; lagMethod?: "fixed" | "AIC" | "BIC" | "AICc" },
): { statistic: number; critical: number; lagOrder: number } {
  checkOptions(options, OCSB_TEST_KEYS, "ocsbTest"); // generated: option-keys.mjs
  const m = options.frequency; const y = x.map(Number); const maxlag = options.maxlag ?? 0; const method = options.lagMethod ?? "fixed";
  let L = maxlag;
  if (method !== "fixed" && maxlag > 0) {
    let best = Infinity; L = 0;
    for (let cand = 0; cand <= maxlag; cand++) {
      const f = ocsbRegression(y, m, cand, m + 1 + maxlag, maxlag);
      const nobs = f.residuals.length; const k = f.rank + 1;
      if (method === "AICc" && nobs - k - 1 <= 0) continue;
      const rss = f.residuals.reduce((s, e) => s + e * e, 0);
      if (!(rss > 0)) continue;
      const aic = nobs * (Math.log((2 * Math.PI * rss) / nobs) + 1) + 2 * k;
      const crit = method === "AIC" ? aic : method === "BIC" ? aic - 2 * k + Math.log(nobs) * k : aic + (2 * k * (k + 1)) / (nobs - k - 1);
      if (crit < best) { best = crit; L = cand; }
    }
  }
  const f = ocsbRegression(y, m, L, m + 1 + L, L);
  return { statistic: f.coefTable.tValue[L + 1]!, critical: ocsbCritical(m), lagOrder: L };
}
